CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, name text NOT NULL, handle text NOT NULL, bio text NOT NULL DEFAULT 'Nuevo en Luna.', hue integer NOT NULL DEFAULT 200);
GRANT SELECT ON public.profiles TO anon;
GRANT SELECT, INSERT, UPDATE ON public.profiles TO authenticated;
GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY profiles_public ON public.profiles FOR SELECT TO anon, authenticated USING (true);
CREATE POLICY profiles_own_insert ON public.profiles FOR INSERT TO authenticated WITH CHECK (id = auth.uid());
CREATE POLICY profiles_own_update ON public.profiles FOR UPDATE TO authenticated USING (id = auth.uid()) WITH CHECK (id = auth.uid());
CREATE TABLE public.profile_private (user_id uuid PRIMARY KEY REFERENCES public.profiles(id) ON DELETE CASCADE, full_name text NOT NULL, birth_date date NOT NULL, zodiac text NOT NULL, simulation_completed boolean NOT NULL DEFAULT false, simulation_completed_at timestamptz);
GRANT SELECT, INSERT, UPDATE ON public.profile_private TO authenticated;
GRANT ALL ON public.profile_private TO service_role;
ALTER TABLE public.profile_private ENABLE ROW LEVEL SECURITY;
CREATE POLICY private_owner_read ON public.profile_private FOR SELECT TO authenticated USING (user_id = auth.uid());
CREATE POLICY private_owner_insert ON public.profile_private FOR INSERT TO authenticated WITH CHECK (user_id = auth.uid());
CREATE POLICY private_owner_update ON public.profile_private FOR UPDATE TO authenticated USING (user_id = auth.uid()) WITH CHECK (user_id = auth.uid());
CREATE OR REPLACE FUNCTION public.validate_private_profile() RETURNS trigger LANGUAGE plpgsql SET search_path = public AS $$ BEGIN IF NEW.birth_date >= CURRENT_DATE THEN RAISE EXCEPTION 'Invalid birth date'; END IF; RETURN NEW; END; $$;
CREATE TRIGGER validate_birth_date BEFORE INSERT OR UPDATE ON public.profile_private FOR EACH ROW EXECUTE FUNCTION public.validate_private_profile();
CREATE TABLE public.groups (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, description text NOT NULL DEFAULT '', category text NOT NULL DEFAULT 'Otros', creator_id uuid NOT NULL REFERENCES public.profiles(id), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.groups TO anon;
GRANT SELECT, INSERT, UPDATE ON public.groups TO authenticated;
GRANT ALL ON public.groups TO service_role;
ALTER TABLE public.groups ENABLE ROW LEVEL SECURITY;
CREATE POLICY groups_public_read ON public.groups FOR SELECT TO anon, authenticated USING (true);
CREATE POLICY groups_create ON public.groups FOR INSERT TO authenticated WITH CHECK (creator_id = auth.uid());
CREATE POLICY groups_creator_update ON public.groups FOR UPDATE TO authenticated USING (creator_id = auth.uid()) WITH CHECK (creator_id = auth.uid());
CREATE TABLE public.group_members (group_id uuid NOT NULL REFERENCES public.groups(id) ON DELETE CASCADE, user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, joined_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(group_id, user_id));
GRANT SELECT, INSERT, DELETE ON public.group_members TO authenticated;
GRANT ALL ON public.group_members TO service_role;
ALTER TABLE public.group_members ENABLE ROW LEVEL SECURITY;
CREATE POLICY members_read ON public.group_members FOR SELECT TO authenticated USING (true);
CREATE POLICY members_join ON public.group_members FOR INSERT TO authenticated WITH CHECK (user_id = auth.uid());
CREATE POLICY members_leave ON public.group_members FOR DELETE TO authenticated USING (user_id = auth.uid());
CREATE INDEX groups_category_idx ON public.groups(category, created_at DESC);
CREATE TABLE public.videos (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id), caption text NOT NULL DEFAULT '', storage_path text NOT NULL, kind text NOT NULL DEFAULT 'video' CHECK (kind IN ('video','reel')), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.videos TO anon;
GRANT SELECT, INSERT, DELETE ON public.videos TO authenticated;
GRANT ALL ON public.videos TO service_role;
ALTER TABLE public.videos ENABLE ROW LEVEL SECURITY;
CREATE POLICY videos_public_read ON public.videos FOR SELECT TO anon, authenticated USING (true);
CREATE POLICY videos_own_insert ON public.videos FOR INSERT TO authenticated WITH CHECK (user_id = auth.uid());
CREATE POLICY videos_own_delete ON public.videos FOR DELETE TO authenticated USING (user_id = auth.uid());